Here's a reusable `ErrorBanner` component. It renders nothing unless there's a non-empty error message.

## TypeScript Version

```tsx
import React from "react";

interface ErrorBannerProps {
  message?: string | null;
  onDismiss?: () => void;
}

export function ErrorBanner({ message, onDismiss }: ErrorBannerProps) {
  // Render nothing if there's no meaningful message
  if (!message || message.trim() === "") {
    return null;
  }

  return (
    <div role="alert" aria-live="assertive" style={styles.banner}>
      <span style={styles.icon} aria-hidden="true">⚠️</span>
      <span style={styles.message}>{message}</span>
      {onDismiss && (
        <button
          type="button"
          onClick={onDismiss}
          aria-label="Dismiss error"
          style={styles.dismiss}
        >
          ×
        </button>
      )}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  banner: {
    display: "flex",
    alignItems: "center",
    gap: "0.5rem",
    padding: "0.75rem 1rem",
    marginBottom: "1rem",
    backgroundColor: "#fdecea",
    color: "#611a15",
    border: "1px solid #f5c6cb",
    borderRadius: "4px",
  },
  icon: {
    flexShrink: 0,
  },
  message: {
    flex: 1,
  },
  dismiss: {
    background: "none",
    border: "none",
    fontSize: "1.25rem",
    lineHeight: 1,
    cursor: "pointer",
    color: "inherit",
  },
};
```

## Example Usage

```tsx
import { useState } from "react";
import { ErrorBanner } from "./ErrorBanner";

export function LoginForm() {
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    try {
      const res = await fetch("/api/login", { method: "POST" });
      if (!res.ok) throw new Error("Invalid username or password.");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong.");
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <ErrorBanner message={error} onDismiss={() => setError(null)} />
      {/* form fields... */}
      <button type="submit">Log in</button>
    </form>
  );
}
```

## Key Points

- **Conditional rendering:** Returning `null` means React renders nothing, with no empty `<div>` left in the DOM.
- **Handles edge cases:** `undefined`, `null`, `""`, and whitespace-only strings all hide the banner.
- **Accessibility:** `role="alert"` makes screen readers announce the error as soon as it appears.
- **Optional dismiss:** The close button only appears if you pass an `onDismiss` handler.

## Alternative: Inline Conditional

If you don't need a separate component, you can conditionally render inline:

```jsx
{error && <div role="alert" className="error-banner">{error}</div>}
```

⚠️ Be careful with this pattern if `error` could be the number `0`, because React will render the `0`. Using `{error ? ... : null}` or `{Boolean(error) && ...}` avoids that.

