  };

  return (
    <form onSubmit={handleSubmit}>
      <ErrorBanner message={error} onDismiss={() => setError(null)} />

      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Email"
      />
      <button type="submit">Log in</button>
    </form>
  );
