## Key Points

- **Conditional rendering:** The component returns `null` when `message` is `null`, `undefined`, an empty string, or only whitespace. Nothing is added to the DOM.
- **Accessibility:** `role="alert"` and `aria-live="assertive"` make screen readers announce the error when it appears. The icon is hidden from assistive tech, and the close button has an `aria-label`.
- **Optional dismiss:** The close button only appears if you pass an `onDismiss` handler.
- **Self-contained logic:** The parent doesn't need to write `{error && <ErrorBanner ... />}`. It can always render `<ErrorBanner message={error} />` and let the component decide.

If you're using plain JavaScript instead of TypeScript, remove the `interface` and type annotations (`React.FC<ErrorBannerProps>`, `string | null`, etc.) and it will work the same way.

Here's a reusable `ProductCard` component that shows a "Sale" badge only when the product has a valid discount:

```jsx
import React from "react";
import "./ProductCard.css";

/**
 * ProductCard
 *
 * Props:
 * - product: {
 *     id: string | number,
 *     name: string,
 *     imageUrl: string,
 *     price: number,          // original price
 *     salePrice?: number,     // discounted price (optional)
 *   }
 * - currency?: string (default "USD")
 * - onAddToCart?: (product) => void
 */
function ProductCard({ product, currency = "USD", onAddToCart }) {
  const { name, imageUrl, price, salePrice } = product;

  // A product counts as discounted only if salePrice is a valid number lower than price
  const isDiscounted =
    typeof salePrice === "number" && salePrice >= 0 && salePrice < price;

  const discountPercent = isDiscounted
    ? Math.round(((price - salePrice) / price) * 100)
    : 0;

  const formatPrice = (value) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(value);

  return (
    <article className="product-card">
      <div className="product-card__image-wrapper">
        {isDiscounted && (
          <span className="product-card__badge" aria-label={`On sale, ${discountPercent}% off`}>
            Sale -{discountPercent}%
          </span>
        )}
        <img className="product-card__image" src={imageUrl} alt={name} loading="lazy" />
      </div>

      <div className="product-card__body">
        <h3 className="product-card__name">{name}</h3>

        <div className="product-card__pricing">
          {isDiscounted ? (
            <>
              <span className="product-card__price product-card__price--sale">
                {formatPrice(salePrice)}
              </span>
              <span className="product-card__price product-card__price--original">
                <span className="visually-hidden">Original price: </span>
                {formatPrice(price)}
              </span>
            </>
          ) : (
            <span className="product-card__price">{formatPrice(price)}</span>
          )}
        </div>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__button"
            onClick={() => onAddToCart(product)}
          >
            Add to Cart
          </button>
        )}
      </div>
    </article>
  );
}

export default ProductCard;
```

