```tsx
import React from "react";
import "./ProductCard.css";

export interface Product {
  id: string;
  name: string;
  imageUrl: string;
  price: number;           // Original price
  salePrice?: number;      // Optional discounted price
  currency?: string;
}

interface ProductCardProps {
  product: Product;
  onAddToCart?: (product: Product) => void;
}

const formatPrice = (amount: number, currency = "USD") =>
  new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);

const ProductCard: React.FC<ProductCardProps> = ({ product, onAddToCart }) => {
  const { name, imageUrl, price, salePrice, currency = "USD" } = product;

  // A product is discounted only if a valid sale price exists and is lower than the original
  const isDiscounted =
    typeof salePrice === "number" && salePrice >= 0 && salePrice < price;

  const discountPercent = isDiscounted
    ? Math.round(((price - salePrice!) / price) * 100)
    : 0;

  return (
    <article className="product-card">
      <div className="product-card__image-wrapper">
        {isDiscounted && (
          <span className="product-card__badge" aria-label={`On sale, ${discountPercent}% off`}>
            Sale -{discountPercent}%
          </span>
        )}
        <img className="product-card__image" src={imageUrl} alt={name} loading="lazy" />
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>

        <div className="product-card__pricing">
          {isDiscounted ? (
            <>
              <span className="product-card__price product-card__price--sale">
                {formatPrice(salePrice!, currency)}
              </span>
              <span className="product-card__price product-card__price--original">
                <span className="visually-hidden">Original price: </span>
                {formatPrice(price, currency)}
              </span>
            </>
          ) : (
            <span className="product-card__price">{formatPrice(price, currency)}</span>
          )}
        </div>

        {onAddToCart && (
          <button className="product-card__button" onClick={() => onAddToCart(product)}>
            Add to Cart
          </button>
        )}
      </div>
    </article>
  );
};

export default ProductCard;
```

