Here's a reusable React component (TypeScript) that fetches paginated items and shows a "Load more" button only while more items are available.

```tsx
import { useCallback, useEffect, useRef, useState } from "react";

interface Item {
  id: number;
  title: string;
}

interface PageResponse {
  items: Item[];
  hasMore: boolean;
}

const PAGE_SIZE = 10;

// Example fetcher: replace with your real API call.
async function fetchItems(page: number, signal?: AbortSignal): Promise<PageResponse> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts?_page=${page}&_limit=${PAGE_SIZE}`,
    { signal }
  );
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);

  const items: Item[] = await res.json();
  const total = Number(res.headers.get("x-total-count") ?? 0);

  // Prefer a server-provided total; fall back to "full page means maybe more".
  const hasMore = total ? page * PAGE_SIZE < total : items.length === PAGE_SIZE;
  return { items, hasMore };
}

export default function LoadMoreList() {
  const [items, setItems] = useState<Item[]>([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const loadPage = useCallback(async (pageToLoad: number) => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    setLoading(true);
    setError(null);
    try {
      const { items: newItems, hasMore } = await fetchItems(pageToLoad, controller.signal);
      setItems(prev => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
      setHasMore(hasMore);
      setPage(pageToLoad);
    } catch (err) {
      if ((err as Error).name !== "AbortError") {
        setError((err as Error).message);
      }
    } finally {
      if (!controller.signal.aborted) setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    loadPage(1);
    return () => abortRef.current?.abort();
  }, [loadPage]);

  return (
    <div>
      <ul>
        {items.map(item => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {error && (
        <p role="alert">
          Error: {error}{" "}
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>Retry</button>
        </p>
      )}

      {loading && <p aria-live="polite">Loading…</p>}

      {/* Button renders only when more items exist */}
      {hasMore && !loading && !error && (
        <button onClick={() => loadPage(page + 1)}>Load more</button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}
```

### How it works

- **`hasMore` controls visibility.** The button renders only when `hasMore` is `true`, and it's hidden while a request is in flight or after an error.
- **Determining `hasMore`:** The best signal comes from the server, such as a total count, a `hasMore` flag, or a `nextCursor`. If none is available, the fallback treats a full page as "maybe more" and a short page as "done."
- **Appending pages:** New results are appended to existing items. Page 1 replaces them, which makes refreshing easy.
- **Robustness:** An `AbortController` cancels stale requests on unmount or repeated clicks. Errors show a Retry button, and empty results get their own message.

### Cursor-based APIs

If your API returns a cursor instead of page numbers, swap `page` for a cursor:

```tsx
const [cursor, setCursor] = useState<string | null>(null);
// after fetch:
setCursor(data.nextCursor);
setHasMore(Boolean(data.nextCursor));
```

The button logic stays the same: `{hasMore && !loading && <button …>Load more</button>}`.

