## `LoadMoreList.jsx`

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Generic paginated list with a "Load more" button.
 *
 * Props:
 *  - fetchPage(page, pageSize) => Promise<{ items: any[], hasMore?: boolean, total?: number }>
 *  - renderItem(item) => ReactNode
 *  - getKey(item) => string | number
 *  - pageSize: number (default 10)
 */
export default function LoadMoreList({
  fetchPage,
  renderItem,
  getKey = (item) => item.id,
  pageSize = 10,
}) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Prevent duplicate requests (e.g., double clicks, StrictMode double effects)
  const inFlight = useRef(false);

  const loadPage = useCallback(
    async (pageToLoad) => {
      if (inFlight.current) return;
      inFlight.current = true;
      setLoading(true);
      setError(null);

      try {
        const { items: newItems, hasMore: apiHasMore, total } =
          await fetchPage(pageToLoad, pageSize);

        setItems((prev) => {
          const merged = [...prev, ...newItems];

          // Determine whether more items exist, in order of reliability:
          // 1. Explicit flag from the API
          // 2. Total count from the API
          // 3. Fallback: a full page suggests there may be more
          if (typeof apiHasMore === "boolean") {
            setHasMore(apiHasMore);
          } else if (typeof total === "number") {
            setHasMore(merged.length < total);
          } else {
            setHasMore(newItems.length === pageSize);
          }

          return merged;
        });

        setPage(pageToLoad);
      } catch (err) {
        setError(err.message || "Failed to load items");
      } finally {
        inFlight.current = false;
        setLoading(false);
      }
    },
    [fetchPage, pageSize]
