/**
 * LoadMoreList
 *
 * Props:
 *  - fetchPage: async (page, pageSize) => ({ items: [], hasMore: boolean })
 *  - pageSize: number of items per request (default 10)
 *  - renderItem: (item) => ReactNode
 *  - getKey: (item) => string | number (default item.id)
 */
export default function LoadMoreList({
  fetchPage,
  pageSize = 10,
  renderItem,
  getKey = (item) => item.id,
}) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Prevents duplicate requests (e.g. double clicks) and
  // state updates after unmount.
  const inFlight = useRef(false);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const loadPage = useCallback(
    async (pageToLoad) => {
      if (inFlight.current) return;
      inFlight.current = true;
      setLoading(true);
      setError(null);

      try {
        const { items: newItems, hasMore: more } = await fetchPage(
          pageToLoad,
          pageSize
        );
        if (!mounted.current) return;

        setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
        setHasMore(more);
        setPage(pageToLoad);
      } catch (err) {
        if (mounted.current) setError(err.message || "Something went wrong");
      } finally {
        inFlight.current = false;
        if (mounted.current) setLoading(false);
      }
    },
    [fetchPage, pageSize]
  );

  // Load the first page on mount
  useEffect(() => {
    loadPage(1);
  }, [loadPage]);

  const isInitialLoad = loading && items.length === 0;

  return (
    <div className="load-more-list">
      {isInitialLoad && <p>Loading…</p>}

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      <ul aria-live="polite">
        {items.map((item) => (
          <li key={getKey(item)}>{renderItem(item)}</li>
        ))}
