        <div role="alert">
          <p>Error: {error}</p>
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>
            Retry
          </button>
        </div>
      )}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && items.length > 0 && !error && (
        <button
          onClick={() => loadPage(page + 1)}
          disabled={loading}
          aria-busy={loading}
        >
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
