## Key details

- **Conditional rendering:** The button renders only when `hasMore` is true, items exist, and there's no error.
- **No duplicate requests:** A `useRef` guard blocks double clicks while a request is in flight, and the button is disabled during loading.
- **Unmount safety:** State isn't updated if the component unmounts mid-request.
- **Error handling:** A retry button replaces "Load more" on failure.
- **Accessibility:** `aria-live` announces new items, `aria-busy` reflects loading, and errors use `role="alert"`.

**Note:** Wrap `fetchPage` in `useCallback` (or define it outside the component, as above) so it doesn't trigger a reload on every render.

Here's a reusable React component that fetches items page by page and only shows the "Load more" button while there are more items to fetch.

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * fetchPage(page, pageSize, signal) must resolve to:
 *   { items: Array, hasMore: boolean }
 */
function LoadMoreList({ fetchPage, pageSize = 10, renderItem }) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const abortRef = useRef(null);

  const loadPage = useCallback(
    async (pageToLoad) => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setLoading(true);
      setError(null);

      try {
        const { items: newItems, hasMore: more } = await fetchPage(
          pageToLoad,
          pageSize,
          controller.signal
        );
        setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
        setHasMore(more);
        setPage(pageToLoad);
      } catch (err) {
        if (err.name !== "AbortError") setError(err.message || "Failed to load items");
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    },
    [fetchPage, pageSize]
  );

  // Load the first page on mount
  useEffect(() => {
    loadPage(1);
    return () => abortRef.current?.abort();
  }, [loadPage]);

  const handleLoadMore = () => {
    if (!loading && hasMore) loadPage(page + 1);
  };

  return (
    <div>
      {items.length === 0 && !loading && !error && <p>No items found.</p>}

      <ul>
        {items.map((item, index) => (
          <li key={item.id ?? index}>
            {renderItem ? renderItem(item) : String(item)}
          </li>
        ))}
      </ul>

      {error && (
        <div role="alert">
          <p>{error}</p>
          <button onClick={() => loadPage(page === 1 && items.length === 0 ? 1 : page + 1)}>
            Retry
          </button>
        </div>
      )}

      {loading && <p aria-live="polite">Loading…</p>}

      {/* Only shown when there are more items to fetch */}
      {hasMore && !loading && !error && items.length > 0 && (
        <button onClick={handleLoadMore}>Load more</button>
      )}
    </div>
  );
}

export default LoadMoreList;
