```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Hook that manages paginated fetching.
 * fetchPage(page, signal) must resolve to { items: [], hasMore: boolean }
 */
function usePaginatedItems(fetchPage) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const abortRef = useRef(null);

  const loadPage = useCallback(
    async (pageToLoad) => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setLoading(true);
      setError(null);
      try {
        const { items: newItems, hasMore: more } = await fetchPage(
          pageToLoad,
          controller.signal
        );
        setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
        setHasMore(more);
        setPage(pageToLoad);
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (abortRef.current === controller) setLoading(false);
      }
    },
    [fetchPage]
  );

  // Load the first page on mount
  useEffect(() => {
    loadPage(1);
    return () => abortRef.current?.abort();
  }, [loadPage]);

  const loadMore = useCallback(() => {
    if (!loading && hasMore) loadPage(page + 1);
  }, [loading, hasMore, page, loadPage]);

  return { items, hasMore, loading, error, loadMore, retry: () => loadPage(page + (items.length ? 1 : 0)) };
}

/**
 * List component that renders a "Load more" button only when more items exist.
 */
export default function ItemList({ fetchPage, renderItem }) {
  const { items, hasMore, loading, error, loadMore, retry } =
    usePaginatedItems(fetchPage);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{renderItem ? renderItem(item) : item.name}</li>
        ))}
      </ul>

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {error && (
        <p role="alert">
          Failed to load items. <button onClick={retry}>Retry</button>
        </p>
      )}

      {/* Only shown when the server says there's more to fetch */}
      {hasMore && !error && (
        <button onClick={loadMore} disabled={loading} aria-busy={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}
