Here's a reusable, type-safe implementation using TypeScript. It handles loading states, errors and race conditions, and hides the button once all items are fetched.

## The Component

```tsx
import { useState, useEffect, useCallback, useRef } from "react";

// ---- Types ----
interface Item {
  id: number;
  title: string;
}

interface PageResponse<T> {
  items: T[];
  hasMore: boolean; // Server tells us if more items exist
}

// ---- Mock API (replace with your real fetch) ----
const TOTAL_ITEMS = 23;

async function fetchItems(page: number, pageSize: number): Promise<PageResponse<Item>> {
  await new Promise((r) => setTimeout(r, 600)); // simulate latency

  const start = page * pageSize;
  const end = Math.min(start + pageSize, TOTAL_ITEMS);
  const items = Array.from({ length: end - start }, (_, i) => ({
    id: start + i + 1,
    title: `Item #${start + i + 1}`,
  }));

  return { items, hasMore: end < TOTAL_ITEMS };
}

// ---- Component ----
interface LoadMoreListProps {
  pageSize?: number;
}

export default function LoadMoreList({ pageSize = 5 }: LoadMoreListProps) {
  const [items, setItems] = useState<Item[]>([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Prevents duplicate requests (e.g., rapid double-clicks)
  const loadingRef = useRef(false);

  const loadMore = useCallback(async () => {
    if (loadingRef.current || !hasMore) return;

    loadingRef.current = true;
    setIsLoading(true);
    setError(null);

    try {
      const { items: newItems, hasMore: more } = await fetchItems(page, pageSize);
      setItems((prev) => [...prev, ...newItems]);
      setPage((p) => p + 1);
      setHasMore(more);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load items");
    } finally {
      loadingRef.current = false;
      setIsLoading(false);
    }
  }, [page, pageSize, hasMore]);

  // Load the first page on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const isInitialLoad = isLoading && items.length === 0;

  return (
    <div style={{ maxWidth: 400, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <h2>Items</h2>

      {isInitialLoad && <p>Loading…</p>}

      {!isLoading && !error && items.length === 0 && !hasMore && (
        <p>No items found.</p>
      )}

      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      {error && (
        <p role="alert" style={{ color: "crimson" }}>
          {error}
        </p>
      )}

      {/* Only rendered when there are more items to fetch */}
      {hasMore && !isInitialLoad && (
        <button onClick={loadMore} disabled={isLoading} aria-busy={isLoading}>
          {isLoading ? "Loading…" : error ? "Retry" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && (
        <p style={{ color: "gray" }}>You've reached the end.</p>
      )}
    </div>
  );
}
```

## How It Works

| Concern | Solution |
|---|---|
| **Show button only when needed** | `{hasMore && ...}` conditionally renders the button. `hasMore` comes from the API response. |
| **Prevent double-fetching** | A `useRef` flag blocks concurrent requests, which avoids stale-state issues that a state check alone can have. |
| **Loading feedback** | The button is disabled and its label changes while fetching. `aria-busy` helps screen readers. |
| **Errors** | The error message is shown, and the button becomes "Retry" without losing loaded items. |
| **Edge states** | Handles the initial load, an empty list and the end of the list. |

## Determining `hasMore`

Use whichever matches your API:

```ts
// 1. Server returns a flag (best)
hasMore: data.hasMore

// 2. Server returns a total count
hasMore: allItems.length < data.total

// 3. Cursor-based pagination
hasMore: data.nextCursor !== null

// 4. No metadata: infer from page size
hasMore: data.items.length === pageSize
```

Option 4 has one drawback: if the total is an exact multiple of `pageSize`, the button appears one extra time and the final fetch returns zero items. After that it hides.

