  fetcher: (page: number) => Promise<{ items: T[]; hasMore: boolean }>
) {
  const [items, setItems] = useState<T[]>([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const loadingRef = useRef(false);

  const loadMore = useCallback(async () => {
    if (loadingRef.current || !hasMore) return;
    loadingRef.current = true;
    setIsLoading(true);
    setError(null);
    try {
      const res = await fetcher(page);
      setItems((prev) => [...prev, ...res.items]);
      setPage((p) => p + 1);
      setHasMore(res.hasMore);
    } catch (e) {
      setError(e as Error);
    } finally {
      loadingRef.current = false;
      setIsLoading(false);
    }
  }, [fetcher, page, hasMore]);

  return { items, hasMore, isLoading, error, loadMore };
}

// Usage:
// const { items, hasMore, isLoading, loadMore } =
//   useLoadMore((page) => fetchItems(page, 10));
```

If you call the hook with an inline fetcher like the usage example, wrap it in `useCallback` so `loadMore` stays stable between renders.

