Here's a React component that fetches items in pages and only shows the "Load more" button while there's more data to fetch:

```jsx
import { useState, useEffect, useCallback } from "react";

const PAGE_SIZE = 10;

// Example fetcher – replace with your real API call.
// Expected to return { items: [...], total: number }
async function fetchItems(page, pageSize) {
  const res = await fetch(`/api/items?page=${page}&limit=${pageSize}`);
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json();
}

export default function LoadMoreList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const loadPage = useCallback(async (pageToLoad) => {
    setLoading(true);
    setError(null);
    try {
      const { items: newItems, total } = await fetchItems(pageToLoad, PAGE_SIZE);

      setItems((prev) => {
        const combined = [...prev, ...newItems];
        // Determine if more items exist.
        // Use `total` if the API provides it; otherwise fall back to
        // checking whether we received a full page.
        setHasMore(
          typeof total === "number"
            ? combined.length < total
            : newItems.length === PAGE_SIZE
        );
        return combined;
      });

      setPage(pageToLoad);
    } catch (err) {
      setError(err.message || "Something went wrong");
    } finally {
      setLoading(false);
    }
  }, []);

  // Load the first page on mount
  useEffect(() => {
    loadPage(1);
  }, [loadPage]);

  const handleLoadMore = () => {
    if (!loading && hasMore) {
      loadPage(page + 1);
    }
  };

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {items.length === 0 && !loading && !error && <p>No items found.</p>}

      {error && (
        <p role="alert" style={{ color: "red" }}>
          {error}{" "}
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>
            Retry
          </button>
        </p>
      )}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !error && (
        <button onClick={handleLoadMore} disabled={loading}>
          {loading ? "Loading..." : "Load more"}
        </button>
      )}
    </div>
  );
}
```

### How it works

1. **State**
   - `items`: accumulated list of fetched items.
   - `page`: the last successfully loaded page.
   - `hasMore`: whether another page exists. This controls the button's visibility.
   - `loading` / `error`: request status.

2. **Determining `hasMore`**
   - If the API returns a `total` count, compare it with the number of items loaded so far.
   - Otherwise, assume there's more data if the last response returned a full page (`newItems.length === PAGE_SIZE`). If the final page happens to be exactly full, one extra click will return an empty page, and the button will then disappear.

3. **Conditional rendering**
   ```jsx
   {hasMore && !error && <button ...>Load more</button>}
   ```
   The button only renders when more data is available. It's disabled while a request is in flight to prevent duplicate fetches.

