## The Component

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Custom hook that manages paginated fetching.
 * `fetchPage(page)` must return a Promise resolving to:
 *   { items: Array, hasMore: boolean }
 */
function usePaginatedFetch(fetchPage) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Prevents duplicate requests (e.g. double clicks or StrictMode double effects)
  const loadingRef = useRef(false);

  const loadPage = useCallback(
    async (pageToLoad) => {
      if (loadingRef.current) return;
      loadingRef.current = true;
      setIsLoading(true);
      setError(null);

      try {
        const { items: newItems, hasMore: more } = await fetchPage(pageToLoad);
        setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
        setHasMore(more);
        setPage(pageToLoad);
      } catch (err) {
        setError(err.message || "Something went wrong");
      } finally {
        loadingRef.current = false;
        setIsLoading(false);
      }
    },
    [fetchPage]
  );

  // Load the first page on mount
  useEffect(() => {
    loadPage(1);
  }, [loadPage]);

  const loadMore = () => {
    if (hasMore && !isLoading) loadPage(page + 1);
  };

  const retry = () => loadPage(items.length === 0 ? 1 : page + 1);

  return { items, hasMore, isLoading, error, loadMore, retry };
}

/**
 * Generic list with a conditional "Load more" button.
 */
export default function LoadMoreList({ fetchPage, renderItem }) {
  const { items, hasMore, isLoading, error, loadMore, retry } =
    usePaginatedFetch(fetchPage);

  return (
    <div className="load-more-list">
      {items.length > 0 && (
        <ul>
          {items.map((item) => (
            <li key={item.id}>{renderItem(item)}</li>
          ))}
        </ul>
      )}

      {!isLoading && !error && items.length === 0 && <p>No items found.</p>}

      {error && (
        <div role="alert">
          <p>Error: {error}</p>
          <button onClick={retry}>Retry</button>
        </div>
      )}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !error && items.length > 0 && (
        <button onClick={loadMore} disabled={isLoading} aria-busy={isLoading}>
          {isLoading ? "Loading..." : "Load more"}
        </button>
      )}

      {isLoading && items.length === 0 && <p>Loading...</p>}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}
```

