## `usePaginatedItems.js`: the data-fetching hook

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Manages paginated fetching.
 * @param {Function} fetchPage - async (page, pageSize) => { items: [], total?: number, hasMore?: boolean }
 * @param {number} pageSize
 */
export function usePaginatedItems(fetchPage, pageSize = 10) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Guards against double-clicks and out-of-order responses
  const loadingRef = useRef(false);

  const loadMore = useCallback(async () => {
    if (loadingRef.current || !hasMore) return;

    loadingRef.current = true;
    setIsLoading(true);
    setError(null);

    try {
      const nextPage = page + 1;
      const result = await fetchPage(nextPage, pageSize);
      const newItems = result.items ?? [];

      setItems((prev) => {
        const combined = [...prev, ...newItems];

        // Determine whether more items exist, in order of reliability:
        if (typeof result.hasMore === "boolean") {
          setHasMore(result.hasMore);           // 1. API tells us explicitly
        } else if (typeof result.total === "number") {
          setHasMore(combined.length < result.total); // 2. Compare against total
        } else {
          setHasMore(newItems.length === pageSize);   // 3. Heuristic: full page => maybe more
        }

        return combined;
      });

      setPage(nextPage);
    } catch (err) {
      setError(err);
    } finally {
      loadingRef.current = false;
      setIsLoading(false);
    }
  }, [fetchPage, page, pageSize, hasMore]);

  // Load the first page on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { items, hasMore, isLoading, error, loadMore };
}
```

