import { useCallback, useEffect, useRef, useState } from "react";

interface Item {
  id: number;
  title: string;
}

interface PageResponse {
  items: Item[];
  hasMore: boolean;
}

interface ItemListProps {
  pageSize?: number;
  fetchPage?: (page: number, pageSize: number, signal: AbortSignal) => Promise<PageResponse>;
}

// Default fetcher: replace the URL with your own API.
async function defaultFetchPage(
  page: number,
  pageSize: number,
  signal: AbortSignal
): Promise<PageResponse> {
  const res = await fetch(`/api/items?page=${page}&limit=${pageSize}`, { signal });
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json();
}

export default function ItemList({
  pageSize = 10,
  fetchPage = defaultFetchPage,
}: ItemListProps) {
  const [items, setItems] = useState<Item[]>([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const abortRef = useRef<AbortController | null>(null);

  const loadPage = useCallback(
    async (pageToLoad: number) => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setLoading(true);
      setError(null);

      try {
        const data = await fetchPage(pageToLoad, pageSize, controller.signal);
        setItems((prev) => (pageToLoad === 1 ? data.items : [...prev, ...data.items]));
        setHasMore(data.hasMore);
        setPage(pageToLoad);
      } catch (err) {
        if ((err as Error).name !== "AbortError") {
          setError((err as Error).message || "Something went wrong");
        }
      } finally {
        if (abortRef.current === controller) setLoading(false);
      }
    },
    [fetchPage, pageSize]
  );

  // Initial load
  useEffect(() => {
    loadPage(1);
    return () => abortRef.current?.abort();
  }, [loadPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {error && (
        <p role="alert">
          {error}{" "}
          <button onClick={() => loadPage(items.length === 0 ? 1 : page + 1)}>
            Retry
          </button>
        </p>
      )}

      {loading && <p aria-live="polite">Loading…</p>}

      {/* Only rendered when the server says there's more to fetch */}
      {hasMore && !loading && !error && (
        <button onClick={() => loadPage(page + 1)}>Load more</button>
      )}
    </div>
  );
}
