import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Hook: manages paginated fetching.
 * `fetchPage(page, pageSize)` must resolve to { items: [], total: number }
 * (or { items: [], hasMore: boolean } — both are supported).
 */
function usePaginatedItems(fetchPage, pageSize = 10) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const inFlight = useRef(false); // prevents double-fetch on rapid clicks

  const loadMore = useCallback(async () => {
    if (inFlight.current || !hasMore) return;
    inFlight.current = true;
    setLoading(true);
    setError(null);

    try {
      const nextPage = page + 1;
      const result = await fetchPage(nextPage, pageSize);
      const newItems = result.items ?? [];

      setItems((prev) => {
        const combined = [...prev, ...newItems];
        // Determine if more items exist
        if (typeof result.hasMore === "boolean") {
          setHasMore(result.hasMore);
        } else if (typeof result.total === "number") {
          setHasMore(combined.length < result.total);
        } else {
          // Fallback: a short page means we've reached the end
          setHasMore(newItems.length === pageSize);
        }
        return combined;
      });
      setPage(nextPage);
    } catch (err) {
      setError(err.message || "Failed to load items");
    } finally {
      inFlight.current = false;
      setLoading(false);
    }
  }, [fetchPage, page, pageSize, hasMore]);

  return { items, hasMore, loading, error, loadMore };
}

/**
 * Component: renders the list and a conditional "Load more" button.
 */
export default function LoadMoreList({ fetchPage, pageSize = 10, renderItem }) {
  const { items, hasMore, loading, error, loadMore } = usePaginatedItems(
    fetchPage,
    pageSize
  );

  // Load the first page on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{renderItem ? renderItem(item) : item.name}</li>
        ))}
      </ul>

      {error && (
        <p role="alert" style={{ color: "crimson" }}>
          {error}{" "}
          <button onClick={loadMore}>Retry</button>
        </p>
      )}

      {/* Only shown when more items are available */}
      {hasMore && !error && (
        <button onClick={loadMore} disabled={loading} aria-busy={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
      {!hasMore && items.length === 0 && !loading && <p>No items found.</p>}
    </div>
  );
}
```

