        <p role="alert" style={{ color: "crimson" }}>
          {error}{" "}
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>
            Retry
          </button>
        </p>
      )}

      {/* Only render the button when more items exist */}
      {hasMore && !error && (
        <button onClick={handleLoadMore} disabled={loading} aria-busy={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}
