## The Hook: `usePaginatedList`

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Manages paginated fetching.
 * @param {Function} fetchPage - async (page, pageSize) => { items: [], total: number }
 * @param {number} pageSize
 */
export function usePaginatedList(fetchPage, pageSize = 10) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Guards against duplicate requests (e.g. double clicks, StrictMode)
  const inFlight = useRef(false);

  const loadMore = useCallback(async () => {
    if (inFlight.current || !hasMore) return;

    inFlight.current = true;
    setIsLoading(true);
    setError(null);

    try {
      const nextPage = page + 1;
      const { items: newItems, total } = await fetchPage(nextPage, pageSize);

      setItems((prev) => {
        const combined = [...prev, ...newItems];
        // Determine if more items exist. Prefer `total` if the API provides it;
        // otherwise fall back to "did we get a full page?"
        const more =
          typeof total === "number"
            ? combined.length < total
            : newItems.length === pageSize;
        setHasMore(more);
        return combined;
      });

      setPage(nextPage);
    } catch (err) {
      setError(err);
    } finally {
      inFlight.current = false;
      setIsLoading(false);
    }
  }, [fetchPage, page, pageSize, hasMore]);

  // Load the first page on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { items, hasMore, isLoading, error, loadMore };
}
```

