## `LoadMoreList.tsx`

```tsx
import { useCallback, useEffect, useRef, useState } from "react";

export interface Page<T> {
  items: T[];
  /** Cursor for the next page, or null/undefined if there are no more items */
  nextCursor?: string | null;
}

interface LoadMoreListProps<T> {
  /** Fetches a page of data. Receives the cursor (undefined for first page). */
  fetchPage: (cursor?: string) => Promise<Page<T>>;
  renderItem: (item: T) => React.ReactNode;
  getKey: (item: T) => string | number;
  emptyMessage?: string;
}

export function LoadMoreList<T>({
  fetchPage,
  renderItem,
  getKey,
  emptyMessage = "No items found.",
}: LoadMoreListProps<T>) {
  const [items, setItems] = useState<T[]>([]);
  const [cursor, setCursor] = useState<string | null | undefined>(undefined);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Prevent duplicate requests and state updates after unmount
  const inFlight = useRef(false);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  const loadMore = useCallback(async () => {
    if (inFlight.current || !hasMore) return;
    inFlight.current = true;
    setIsLoading(true);
    setError(null);

    try {
      const page = await fetchPage(cursor ?? undefined);
      if (!isMounted.current) return;

      setItems((prev) => [...prev, ...page.items]);
      setCursor(page.nextCursor);
      setHasMore(Boolean(page.nextCursor));
    } catch (err) {
      if (!isMounted.current) return;
      setError(err instanceof Error ? err.message : "Failed to load items.");
    } finally {
      inFlight.current = false;
      if (isMounted.current) setIsLoading(false);
    }
  }, [cursor, hasMore, fetchPage]);

  // Load the first page on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const isInitialLoad = isLoading && items.length === 0;

  return (
    <div>
      {isInitialLoad && <p>Loading…</p>}

      {!isLoading && !error && items.length === 0 && !hasMore && (
        <p>{emptyMessage}</p>
      )}

      <ul aria-live="polite" aria-busy={isLoading}>
        {items.map((item) => (
          <li key={getKey(item)}>{renderItem(item)}</li>
        ))}
      </ul>

      {error && (
        <p role="alert" style={{ color: "crimson" }}>
          {error}
        </p>
      )}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !isInitialLoad && (
        <button type="button" onClick={loadMore} disabled={isLoading}>
          {isLoading ? "Loading…" : error ? "Retry" : "Load more"}
        </button>
      )}
    </div>
  );
}
```

