import { useState, useEffect, useCallback, useRef } from "react";

/**
 * Generic hook for paginated "load more" fetching.
 * fetchPage(page) must resolve to { items: [], hasMore: boolean }
 */
function useLoadMore(fetchPage) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Guards against duplicate requests (e.g. rapid double clicks)
  const inFlight = useRef(false);

  const loadMore = useCallback(async () => {
    if (inFlight.current || !hasMore) return;

    inFlight.current = true;
    setLoading(true);
    setError(null);

    try {
      const { items: newItems, hasMore: more } = await fetchPage(page);
      setItems((prev) => [...prev, ...newItems]);
      setHasMore(more);
      setPage((p) => p + 1);
    } catch (err) {
      setError(err.message || "Something went wrong");
    } finally {
      inFlight.current = false;
      setLoading(false);
    }
  }, [fetchPage, page, hasMore]);

  return { items, hasMore, loading, error, loadMore };
}

