          <li key={item.id} style={{ marginBottom: 8 }}>
            <strong>{item.title}</strong>
          </li>
        ))}
      </ul>

      {error && (
        <p role="alert" style={{ color: "crimson" }}>
          {error}
        </p>
      )}

      {/* Button only renders when there's more to fetch */}
      {hasMore && !isInitialLoad && (
        <button onClick={loadMore} disabled={loading} aria-busy={loading}>
          {loading ? "Loading…" : error ? "Retry" : "Load more"}
        </button>
      )}

      {!hasMore && items.length > 0 && (
        <p style={{ color: "#666" }}>You've reached the end.</p>
      )}
    </div>
  );
}
```

## Key points

**How "more items" is determined** — the `hasMore` flag drives visibility. The fetcher computes it from one of:
1. **Total count** (`page * size < total`), the most accurate.
2. **Full-page heuristic** (`data.length === PAGE_SIZE`), used when no total is available. Caveat: if the total is an exact multiple of the page size, the user sees one extra click that returns nothing, after which the button disappears.
3. **Cursor APIs**: return `hasMore: Boolean(response.nextCursor)` and store the cursor instead of a page number.

**Robustness details**
- `inFlight` ref prevents duplicate requests from double-clicks, since state updates are async.
- The button is disabled while loading, and switches to "Retry" on error without losing already-loaded items.
- The button is hidden during the initial load so it doesn't flash before data arrives.
- Distinct states for empty results vs. end-of-list.

## Cursor-based variant (if your API uses cursors)

```jsx
async function fetchPage(cursor) {
  const res = await fetch(`/api/items?cursor=${cursor ?? ""}`);
  const { items, nextCursor } = await res.json();
  return { items, nextCursor, hasMore: nextCursor != null };
}
```

In the hook, replace `page` with a `cursor` state and set it from `nextCursor` after each fetch.

