Here's a product card component that shows a "Sale" badge only when the product has a discount.

```jsx
import React from "react";
import "./ProductCard.css";

function ProductCard({ product }) {
  const { name, image, price, salePrice, description } = product;

  // A product is discounted if it has a sale price lower than the regular price
  const isOnSale =
    typeof salePrice === "number" && salePrice >= 0 && salePrice < price;

  const discountPercent = isOnSale
    ? Math.round(((price - salePrice) / price) * 100)
    : 0;

  const formatPrice = (value) =>
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(value);

  return (
    <div className="product-card">
      {isOnSale && <span className="product-card__badge">Sale</span>}

      <img className="product-card__image" src={image} alt={name} />

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>
        {description && (
          <p className="product-card__description">{description}</p>
        )}

        <div className="product-card__prices">
          {isOnSale ? (
            <>
              <span className="product-card__price product-card__price--sale">
                {formatPrice(salePrice)}
              </span>
              <span className="product-card__price product-card__price--original">
                {formatPrice(price)}
              </span>
              <span className="product-card__discount">-{discountPercent}%</span>
            </>
          ) : (
            <span className="product-card__price">{formatPrice(price)}</span>
          )}
        </div>

        <button className="product-card__button">Add to Cart</button>
      </div>
    </div>
  );
}

export default ProductCard;
```

