Here's a self-contained component that paginates from an API and only renders the button while more items remain.

```jsx
import { useState, useEffect, useCallback, useRef } from "react";

const PAGE_SIZE = 20;

// Replace with your real API call.
// Should return { items: [...], total: number }
// or { items: [...], hasMore: boolean }
async function fetchItems({ page, pageSize, signal }) {
  const res = await fetch(`/api/items?page=${page}&limit=${pageSize}`, { signal });
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.json();
}

export default function ItemList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const controllerRef = useRef(null);

  const loadPage = useCallback(async (pageToLoad) => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    setLoading(true);
    setError(null);

    try {
      const data = await fetchItems({
        page: pageToLoad,
        pageSize: PAGE_SIZE,
        signal: controller.signal,
      });

      setItems((prev) =>
        pageToLoad === 1 ? data.items : [...prev, ...data.items]
      );

      // Prefer an explicit flag; otherwise fall back to total, then page size.
      const more =
        typeof data.hasMore === "boolean"
          ? data.hasMore
          : typeof data.total === "number"
          ? pageToLoad * PAGE_SIZE < data.total
          : data.items.length === PAGE_SIZE;

      setHasMore(more);
      setPage(pageToLoad);
    } catch (err) {
      if (err.name !== "AbortError") setError(err.message);
    } finally {
      if (controllerRef.current === controller) setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    loadPage(1);
    return () => controllerRef.current?.abort();
  }, [loadPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && (
        <p role="alert">
          Something went wrong: {error}{" "}
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>
            Retry
          </button>
        </p>
      )}

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {hasMore && !error && (
        <button onClick={() => loadPage(page + 1)} disabled={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {loading && items.length === 0 && <p>Loading…</p>}
    </div>
  );
}
```

**How the button visibility works**

- `hasMore` is the single source of truth, and the button renders only when it's `true`.
- After each fetch, `hasMore` is determined by the first available signal:
  1. `data.hasMore` – an explicit flag from the API
  2. `data.total` – compares loaded count to the total
  3. Fallback: if the page came back full (`items.length === PAGE_SIZE`), assume there's more. A short page means you've reached the end.
- It starts as `false`, so the button doesn't flash before the first response.

**Details worth noting**

- The button is disabled while loading to prevent duplicate requests.
- An `AbortController` cancels stale requests on unmount.
- If your API uses cursors, replace `page` with a `nextCursor` state, and set `hasMore = Boolean(data.nextCursor)`.
- The fallback heuristic shows a button that yields an empty page if the total is an exact multiple of the page size. Returning `hasMore` or `total` from the API avoids this.

