  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const inFlight = useRef(false);

  const loadPage = useCallback(async (pageToLoad, signal) => {
    if (inFlight.current) return;
    inFlight.current = true;
    setLoading(true);
    setError(null);

    try {
      const { items: newItems, total } = await fetchItems(pageToLoad, PAGE_SIZE, signal);

      setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));

      // More items exist if we've loaded fewer than the total.
      // Fallback: a full page suggests there may be more.
      const loadedSoFar = (pageToLoad - 1) * PAGE_SIZE + newItems.length;
      setHasMore(
        typeof total === "number"
          ? loadedSoFar < total
          : newItems.length === PAGE_SIZE
      );
      setPage(pageToLoad);
    } catch (err) {
      if (err.name !== "AbortError") setError(err.message);
    } finally {
      inFlight.current = false;
      setLoading(false);
    }
  }, []);

