    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {error && (
        <p role="alert">
          Error: {error}{" "}
          <button onClick={() => loadPage(page + (items.length ? 1 : 0) || 1)}>
            Retry
          </button>
        </p>
      )}

      {loading && <p>Loading…</p>}

      {hasMore && !loading && (
        <button onClick={() => loadPage(page + 1)}>Load more</button>
      )}
    </div>
  );
