  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const abortRef = useRef(null);

  const loadPage = useCallback(async (pageToLoad) => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    setLoading(true);
    setError(null);

    try {
      const data = await fetchItems({
        page: pageToLoad,
        pageSize: PAGE_SIZE,
        signal: controller.signal,
      });

      setItems((prev) =>
        pageToLoad === 1 ? data.items : [...prev, ...data.items]
      );

      // More items exist only if we've loaded fewer than the total.
      // Fallback: a full page suggests there may be another one.
      const loadedCount = (pageToLoad - 1) * PAGE_SIZE + data.items.length;
      setHasMore(
        typeof data.total === "number"
          ? loadedCount < data.total
          : data.items.length === PAGE_SIZE
      );
      setPage(pageToLoad);
    } catch (err) {
      if (err.name !== "AbortError") setError(err.message);
    } finally {
      if (abortRef.current === controller) setLoading(false);
    }
  }, []);

  // Initial load + cleanup
  useEffect(() => {
    loadPage(1);
    return () => abortRef.current?.abort();
  }, [loadPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && (
        <p role="alert">
          Something went wrong: {error}{" "}
          <button onClick={() => loadPage(items.length ? page + 1 : 1)}>
            Retry
          </button>
        </p>
      )}

      {!loading && !error && items.length === 0 && <p>No items found.</p>}

      {hasMore && !error && (
        <button onClick={() => loadPage(page + 1)} disabled={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {loading && items.length === 0 && <p>Loading…</p>}
    </div>
  );
}
```

**How it works**

- **`hasMore` state** controls visibility. The button is rendered only when `hasMore` is true.
- **Determining `hasMore`:** if the API returns a `total`, compare it to the number of items loaded. If not, it falls back to checking whether the page came back full. If your API returns a `nextCursor`, use `setHasMore(Boolean(data.nextCursor))` instead and store the cursor in place of `page`.
- **Disabled while loading** prevents duplicate requests from double clicks.
- **AbortController** cancels in-flight requests on unmount or when a new request begins, avoiding state updates on an unmounted component and race conditions.
- **Error handling** shows a retry button and hides "Load more" until the error is resolved.

**Cursor-based variant (the key changes)**

```jsx
const [cursor, setCursor] = useState(null);

// after fetching:
setItems((prev) => [...prev, ...data.items]);
setCursor(data.nextCursor);
setHasMore(Boolean(data.nextCursor));
```

Then call your API with `?cursor=${cursor}` on each "Load more" click.

