```jsx
import React from 'react';

function ErrorBanner({ message, onClose }) {
  if (!message) {
    return null;
  }

  return (
    <div
      role="alert"
      style={{
        backgroundColor: '#fee2e2',
        color: '#991b1b',
        border: '1px solid #f87171',
        borderRadius: '4px',
        padding: '12px 16px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '16px',
      }}
    >
      <span>{message}</span>
      {onClose && (
        <button
          onClick={onClose}
          aria-label="Dismiss error"
          style={{
            background: 'none',
            border: 'none',
            color: '#991b1b',
            fontSize: '18px',
            fontWeight: 'bold',
            cursor: 'pointer',
            marginLeft: '12px',
          }}
        >
          &times;
        </button>
      )}
    </div>
  );
}

export default ErrorBanner;
```

