import React from 'react';

const ProductCard = ({ name, price, originalPrice, imageUrl, onAddToCart }) => {
  const isDiscounted = originalPrice && originalPrice > price;

  return (
    <div className="relative max-w-xs overflow-hidden rounded-lg border border-gray-200 bg-white shadow-sm">
      {/* Conditional Sale Badge */}
      {isDiscounted && (
        <span className="absolute top-3 left-3 rounded-full bg-red-600 px-3 py-1 text-xs font-semibold text-white">
          Sale
        </span>
      )}

      {/* Product Image */}
      <img
        src={imageUrl}
        alt={name}
        className="h-48 w-full object-cover"
      />

      {/* Product Details */}
      <div className="p-4">
        <h3 className="truncate text-lg font-semibold text-gray-800">{name}</h3>

        <div className="mt-2 flex items-baseline gap-2">
          <span className="text-xl font-bold text-gray-900">
            ${price.toFixed(2)}
          </span>
          {isDiscounted && (
            <span className="text-sm text-gray-500 line-through">
              ${originalPrice.toFixed(2)}
            </span>
          )}
        </div>

        <button
          onClick={onAddToCart}
          className="mt-4 w-full rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-blue-700"
        >
          Add to Cart
        </button>
      </div>
    </div>
  );
};

export default ProductCard;
