        {isOnSale && <span className="product-card__badge">Sale</span>}
      </div>

      <h3>{name}</h3>

      <div className="product-card__pricing">
        <strong>{formatPrice(price)}</strong>
        {isOnSale && <s>{formatPrice(originalPrice)}</s>}
      </div>
    </article>
  );
}
