Here's a React component with a `Sale` badge that conditionally renders when the product is discounted:

```jsx
import React from 'react';
import './ProductCard.css';

function ProductCard({ product }) {
  const { name, image, price, originalPrice } = product;

  // Product is discounted if it has an original price higher than current price
  const isDiscounted = originalPrice && originalPrice > price;

  // Calculate discount percentage
  const discountPercentage = isDiscounted
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <div className="product-card">
      <div className="product-image-container">
        <img src={image} alt={name} className="product-image" />

        {/* Sale badge only shows when discounted */}
        {isDiscounted && (
          <span className="sale-badge">
            Sale {discountPercentage > 0 && `- ${discountPercentage}%`}
          </span>
        )}
      </div>

      <div className="product-info">
        <h3 className="product-name">{name}</h3>

        <div className="product-pricing">
          <span className="current-price">${price.toFixed(2)}</span>
          {isDiscounted && (
            <span className="original-price">${originalPrice.toFixed(2)}</span>
          )}
        </div>

        <button className="add-to-cart-btn">Add to Cart</button>
      </div>
    </div>
  );
}

export default ProductCard;
