import { useState, useEffect, useCallback } from "react";

function LoadMoreList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const PAGE_SIZE = 10;

  // Simulated API call — replace with your real fetch
  const fetchItems = useCallback(async (page) => {
    const response = await fetch(`/api/items?page=${page}&limit=${PAGE_SIZE}`);
    if (!response.ok) {
      throw new Error("Failed to fetch items");
    }
    const { data, total } = await response.json();
    return { data, total };
  }, []);

  const loadItems = useCallback(async (pageToLoad) => {
    setIsLoading(true);
    setError(null);
    try {
      const { data, total } = await fetchItems(pageToLoad);
      setItems((prev) => [...prev, ...data]);
      setHasMore(pageToLoad * PAGE_SIZE < total);
    } catch (err) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  }, [fetchItems]);

  // Load the first page on mount
  useEffect(() => {
    loadItems(1);
  }, [loadItems]);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    loadItems(nextPage);
  };

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p role="alert">Error: {error}</p>}

