      {hasMore && !isLoading && (
        <button onClick={handleLoadMore}>Load more</button>
      )}

      {isLoading && <p>Loading…</p>}

      {!hasMore && items.length > 0 && <p>No more items to load.</p>}
    </div>
  );
}

export default LoadMoreList;
