# Load More Component

Here's a complete example with a custom hook that handles fetching and tracks whether more items exist:

## The Hook

```jsx
// usePaginatedItems.js
import { useState, useCallback } from 'react';

export function usePaginatedItems(fetchPage, pageSize = 10) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [error, setError] = useState(null);

  const loadMore = useCallback(async () => {
    if (isLoading || !hasMore) return;

    setIsLoading(true);
    setError(null);

    try {
      const { data, hasMore: moreAvailable } = await fetchPage(page, pageSize);
      setItems((prev) => [...prev, ...data]);
      setHasMore(moreAvailable);
      setPage((p) => p + 1);
    } catch (err) {
      setError('Failed to load items. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [fetchPage, page, pageSize, isLoading, hasMore]);

  return { items, isLoading, hasMore, error, loadMore };
}
```

## The Component

```jsx
// ItemList.jsx
import { useEffect } from 'react';
import { usePaginatedItems } from './usePaginatedItems';

// Example API call — adapt to your backend
async function fetchPage(page, pageSize) {
  const response = await fetch(
    `/api/items?page=${page}&limit=${pageSize}`
  );
  if (!response.ok) throw new Error('Request failed');

  const { data, total } = await response.json();
  const hasMore = page * pageSize < total;

  return { data, hasMore };
}

export default function ItemList() {
  const { items, isLoading, hasMore, error, loadMore } =
    usePaginatedItems(fetchPage);

  // Load the first batch on mount
  useEffect(() => {
    loadMore();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="item-list">
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p className="error" role="alert">{error}</p>}

      {/* Button only renders when there's more to fetch */}
      {hasMore && (
        <button onClick={loadMore} disabled={isLoading}>
          {isLoading ? 'Loading…' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && (
        <p className="end-message">You've reached the end.</p>
      )}
    </div>
  );
}
```

## Key Points

- **Conditional rendering**: `{hasMore && <button>...}` — the button only appears when the API indicates more items exist (e.g., `page * pageSize < total`, or a `nextCursor` is returned).
- **Disabled while loading**: Prevents duplicate requests from double-clicks.
- **Functional state update**: `setItems((prev) => [...prev, ...data])` avoids stale-state bugs.
- **Guard in `loadMore`**: Extra safety check so the hook won't fetch even if called unexpectedly.

## Alternative: Server-driven `hasMore`

If your API returns a cursor or a `next` link instead of a total count, adjust `fetchPage`:

```js
const hasMore = Boolean(data.nextCursor);
```

