# Product Card with Conditional Sale Badge

The key idea: derive a single `isOnSale` boolean from the data, then use it to gate **both** the badge and the strikethrough price. That way the two can never disagree.

```jsx
// ProductCard.jsx
import React from "react";
import "./ProductCard.css";

function formatPrice(amount, currency = "USD") {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
  }).format(amount);
}

export default function ProductCard({ product, onAddToCart }) {
  const { name, imageUrl, price, compareAtPrice, currency = "USD" } = product;

  // A product is on sale only if there's a valid "was" price that's higher.
  const isOnSale =
    Number.isFinite(compareAtPrice) && compareAtPrice > price;

  const discountPercent = isOnSale
    ? Math.round(((compareAtPrice - price) / compareAtPrice) * 100)
    : 0;

  return (
    <article className="product-card">
      <div className="product-card__media">
        <img
          className="product-card__image"
          src={imageUrl}
          alt={name}
          loading="lazy"
        />

        {isOnSale && (
          <span className="product-card__badge">
            Sale
            {discountPercent > 0 && (
              <span className="product-card__badge-detail">
                {" "}
                −{discountPercent}%
              </span>
            )}
          </span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>

        <p className="product-card__price">
          <span className="product-card__price-current">
            {formatPrice(price, currency)}
          </span>

          {isOnSale && (
            <>
              <span className="product-card__price-original" aria-hidden="true">
                {formatPrice(compareAtPrice, currency)}
              </span>
              {/* Strikethrough isn't announced by screen readers, so spell it out. */}
              <span className="visually-hidden">
                Was {formatPrice(compareAtPrice, currency)}, now{" "}
                {formatPrice(price, currency)}
              </span>
            </>
          )}
        </p>

        <button
          type="button"
          className="product-card__cta"
          onClick={() => onAddToCart?.(product)}
        >
          Add to cart
        </button>
      </div>
    </article>
  );
}
