# Product Card with Conditional Sale Badge

The key is to derive a single `isOnSale` boolean and use it for *both* the badge and the strikethrough price, so they can never disagree.

```tsx
// ProductCard.tsx
import './ProductCard.css';

export type Product = {
  id: string;
  name: string;
  imageUrl: string;
  price: number;              // current selling price
  originalPrice?: number | null; // pre-discount price, if any
  currency?: string;
};

type ProductCardProps = {
  product: Product;
  onAddToCart?: (product: Product) => void;
};

const formatPrice = (amount: number, currency = 'USD') =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);

export function ProductCard({ product, onAddToCart }: ProductCardProps) {
  const { name, imageUrl, price, originalPrice, currency } = product;

  // Single source of truth: on sale only when a real original price
  // exists AND it's strictly higher than the current price.
  const isOnSale =
    typeof originalPrice === 'number' &&
    Number.isFinite(originalPrice) &&
    originalPrice > price;

  const discountPercent = isOnSale
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <article className="product-card">
      <div className="product-card__media">
        <img src={imageUrl} alt={name} loading="lazy" />

        {isOnSale && (
          <span className="product-card__badge">
            Sale
            {discountPercent > 0 && (
              <span className="product-card__badge-percent"> −{discountPercent}%</span>
            )}
          </span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__name">{name}</h3>

        <p className="product-card__price">
          <span className="product-card__price-current">
            {formatPrice(price, currency)}
          </span>

          {isOnSale && (
            <s className="product-card__price-original">
              <span className="sr-only">Original price: </span>
              {formatPrice(originalPrice, currency)}
            </s>
          )}
        </p>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__cta"
            onClick={() => onAddToCart(product)}
          >
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
```

