# Product Card with Conditional Sale Badge

```jsx
import React from 'react';
import './ProductCard.css';

const ProductCard = ({ product }) => {
  const { name, image, price, originalPrice, currency = '$' } = product;

  // Product is on sale if originalPrice exists and is greater than the current price
  const isOnSale =
    typeof originalPrice === 'number' && originalPrice > price;

  const discountPercent = isOnSale
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <div className="product-card">
      <div className="product-card__image-wrapper">
        {isOnSale && (
          <span className="product-card__badge" aria-label="On sale">
            Sale {discountPercent}% off
          </span>
        )}
        <img
          className="product-card__image"
          src={image}
          alt={name}
          loading="lazy"
        />
      </div>

      <div className="product-card__body">
        <h3 className="product-card__name">{name}</h3>

        <div className="product-card__pricing">
          <span className="product-card__price">
            {currency}
            {price.toFixed(2)}
          </span>

          {isOnSale && (
            <span className="product-card__original-price">
              {currency}
              {originalPrice.toFixed(2)}
            </span>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProductCard;
```

