      setItems((prev) => (pageNum === 1 ? data.items : [...prev, ...data.items]));

      // Determine if there are more items to fetch
      const loadedCount = pageNum * PAGE_SIZE;
      setHasMore(loadedCount < data.total && data.items.length > 0);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    fetchItems(1);
  }, [fetchItems]);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchItems(nextPage);
  };

  return (
    <div className="load-more-list">
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p className="error">Error: {error}</p>}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !error && (
        <button onClick={handleLoadMore} disabled={loading}>
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && (
        <p className="end-message">You've reached the end.</p>
      )}
    </div>
  );
}

export default LoadMoreList;
```

## Key points

1. **`hasMore` state** — the single source of truth for whether the button renders. It's updated after every fetch based on the API's total count (or the length of the returned page).

2. **Conditional rendering** — `{hasMore && !error && <button>…</button>}` ensures the button disappears once all items are loaded.

3. **Two ways to detect "no more items"** — pick whichever your API supports:
   - **Total count**: `loadedCount < total`
   - **Short page**: `data.items.length === PAGE_SIZE` (if the API returns fewer than requested, you're at the end)

4. **Loading state** — the button is disabled while a request is in flight to prevent double-fetches.

5. **`useCallback`** — keeps `fetchItems` stable so the initial-load `useEffect` doesn't re-run on every render.

## Alternative: cursor-based pagination

If your API uses cursors instead of page numbers, swap the logic:

```jsx
const [cursor, setCursor] = useState(null);

const fetchItems = async (nextCursor = null) => {
  const url = nextCursor
    ? `/api/items?cursor=${nextCursor}`
    : `/api/items`;
  const data = await (await fetch(url)).json();

  setItems((prev) => (nextCursor ? [...prev, ...data.items] : data.items));
  setCursor(data.nextCursor);
  setHasMore(Boolean(data.nextCursor)); // button shows only if a next cursor exists
};
```

The rendering logic stays identical — `hasMore` still gates the button.

