      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPage(1);
  }, [loadPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p role="alert">{error}</p>}

      {/* Button only renders when the API says there are more items */}
      {hasMore && (
        <button
          type="button"
          onClick={() => loadPage(page + 1)}
          disabled={loading}
        >
          {loading ? 'Loading...' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>No more items.</p>}
    </div>
  );
}
```

The important part is:

```jsx
{hasMore && <button onClick={() => loadPage(page + 1)}>Load more</button>}
```

`hasMore` should come from your API response, for example `hasMore: items.length < total`.

# Load More Component

Here's a React component that fetches paginated data and only shows the "Load more" button when there are more items available:

```jsx
import React, { useState, useEffect, useCallback } from 'react';

// Simulated API — replace with your real fetch call
const fetchItems = async (page, pageSize = 10) => {
  const res = await fetch(`/api/items?page=${page}&limit=${pageSize}`);
  if (!res.ok) throw new Error('Failed to fetch');
  const data = await res.json();
  // Assume the API returns { items: [...], total: number }
  return data;
};

const PAGE_SIZE = 10;

export default function ItemList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const loadPage = useCallback(async (pageToLoad) => {
    setLoading(true);
    setError(null);
    try {
      const { items: newItems, total } = await fetchItems(pageToLoad, PAGE_SIZE);
      setItems((prev) => (pageToLoad === 1 ? newItems : [...prev, ...newItems]));
      setTotal(total);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    loadPage(1);
  }, [loadPage]);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    loadPage(nextPage);
  };

  // Derived: do we have more items to fetch?
  const hasMore = items.length < total;

  if (error) return <p role="alert">Error: {error}</p>;

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {/* Only render the button when there are more items */}
      {hasMore && (
        <button onClick={handleLoadMore} disabled={loading}>
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}
```

## Key points

**1. How `hasMore` is derived**
The cleanest approach is to compare loaded items against a total:
```js
const hasMore = items.length < total;
```
If your API doesn't return a `total`, use one of these alternatives:
- **Length heuristic:** `hasMore = lastPage.length === PAGE_SIZE` (works if the API returns full pages until the last one)
- **Cursor-based API:** have the server return a `nextCursor` field and use `hasMore = Boolean(nextCursor)`

**2. Conditional rendering**
`{hasMore && <button>…</button>}` — the button is simply not in the DOM when there's nothing more to load.

**3. Guard against double-clicks**
The `disabled={loading}` prop prevents firing another request while one is in flight.

**4. Functional state updates**
`setItems((prev) => [...prev, ...newItems])` avoids stale-closure bugs when appending pages.

**5. Reset on page 1**
If you ever add filters or a refresh, `pageToLoad === 1` replaces the list instead of appending — a pattern that's easy to extend later.

```jsx
import React, { useState, useEffect, useCallback } from 'react';

const PAGE_SIZE = 10;

export default function LoadMoreList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchPage = useCallback(async (pageNumber) => {
    setLoading(true);
    setError(null);

    try {
      const res = await fetch(`/api/items?page=${pageNumber}&limit=${PAGE_SIZE}`);
      if (!res.ok) throw new Error('Failed to load items');

      const data = await res.json();

      // Adjust this to match your API response shape.
      // Example response: { items: [...], hasMore: true }
      const newItems = data.items ?? [];
      const more = data.hasMore ?? newItems.length === PAGE_SIZE;

      setItems(prev => (pageNumber === 1 ? newItems : [...prev, ...newItems]));
      setHasMore(more);
      setPage(pageNumber);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
      if (pageNumber === 1) setInitialLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPage(1);
  }, [fetchPage]);

  const handleLoadMore = () => {
    if (!loading && hasMore) {
      fetchPage(page + 1);
    }
  };

  return (
    <div>
      {initialLoading ? (
        <p>Loading...</p>
      ) : (
        <>
          <ul>
            {items.map(item => (
              <li key={item.id}>{item.name}</li>
            ))}
          </ul>

          {error && <p role="alert">{error}</p>}

          {/* Show the button only when there are more items to fetch */}
          {hasMore && (
            <button onClick={handleLoadMore} disabled={loading}>
              {loading ? 'Loading...' : 'Load more'}
            </button>
          )}

          {!hasMore && items.length > 0 && <p>No more items.</p>}
        </>
      )}
    </div>
  );
}
```

If your API returns a `total` count instead of `hasMore`, compute it like this:

```js
const more = pageNumber * PAGE_SIZE < data.total;
```

# Load More Component

Here's a clean, reusable React component that fetches paginated data and only shows the "Load more" button when there are more items available.

```jsx
import { useState, useEffect, useCallback } from "react";

function LoadMoreList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const PAGE_SIZE = 10;

  const fetchItems = useCallback(async (pageNumber) => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(
        `https://api.example.com/items?page=${pageNumber}&limit=${PAGE_SIZE}`
      );
      if (!res.ok) throw new Error(`Request failed: ${res.status}`);

      const data = await res.json();

      // Assume API returns { items: [...], total: number }
      setItems((prev) => [...prev, ...data.items]);

      // Determine if there are more items to fetch.
      // Option A: API returns a total count
      const loadedSoFar = (pageNumber - 1) * PAGE_SIZE + data.items.length;
      setHasMore(loadedSoFar < data.total);

      // Option B (if no total is provided): a short page means we're done
      // setHasMore(data.items.length === PAGE_SIZE);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    fetchItems(1);
  }, [fetchItems]);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchItems(nextPage);
  };

  return (
    <div className="load-more-list">
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p className="error">Error: {error}</p>}

      {/* Only render the button when there is more data AND we're not loading */}
      {hasMore && (
        <button onClick={handleLoadMore} disabled={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}

      {/* Optional: show a friendly end-of-list message */}
      {!hasMore && items.length > 0 && (
        <p className="end-of-list">You've reached the end.</p>
      )}
    </div>
  );
}

export default LoadMoreList;
```

## How it works

| State | Purpose |
| --- | --- |
| `items` | Accumulated list across all fetched pages |
| `page` | The last requested page number |
| `hasMore` | **Controls button visibility** — `true` only while more data exists |
| `loading` | Disables the button during an in-flight request |
| `error` | Surfaces fetch failures without hiding the button |

## Key details

- **Button visibility**: `{hasMore && <button>…</button>}` — the button is completely removed from the DOM once `hasMore` flips to `false`, not just hidden.
- **Two ways to compute `hasMore`**:
  - If your API returns a `total` count (Option A), compare the number of loaded items to the total.
  - If it doesn't (Option B), treat a page shorter than `PAGE_SIZE` as the last page.
- **Race-condition safety**: using the functional `setItems(prev => [...prev, ...])` form prevents stale-state bugs if multiple fetches overlap.
- **Accessibility**: the button is disabled (not removed) while loading, so the user gets feedback that something is happening.

## Usage

```jsx
<LoadMoreList />
```

Swap the `fetch` URL and the `data.items` / `data.total` shape to match your actual API, and you're good to go.

# Load More Button Component

Here's a React component that fetches paginated data and only renders the "Load more" button when more items are available:

```jsx
import { useCallback, useEffect, useRef, useState } from 'react';

const PAGE_SIZE = 10;

export default function PaginatedList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Prevent state updates after unmount / stale responses
  const abortRef = useRef(null);

  const fetchPage = useCallback(async (pageToLoad) => {
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    setLoading(true);
    setError(null);

    try {
      const res = await fetch(
        `/api/items?page=${pageToLoad}&limit=${PAGE_SIZE}`,
        { signal: controller.signal }
      );
      if (!res.ok) throw new Error(`Request failed: ${res.status}`);

      const data = await res.json();
      // Expecting: { items: [...], total: number } — adapt to your API
      const newItems = data.items ?? [];

      setItems((prev) =>
        pageToLoad === 1 ? newItems : [...prev, ...newItems]
      );

      // Determine if more pages exist
      const loadedCount =
        pageToLoad === 1 ? newItems.length : items.length + newItems.length;
      setHasMore(
        newItems.length === PAGE_SIZE &&
          (data.total == null || loadedCount < data.total)
      );
    } catch (err) {
      if (err.name !== 'AbortError') setError(err.message);
    } finally {
      if (!controller.signal.aborted) setLoading(false);
    }
  }, [items.length]);

  // Initial load
  useEffect(() => {
    fetchPage(1);
    return () => abortRef.current?.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchPage(nextPage);
  };

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p role="alert">Error: {error}</p>}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !error && (
        <button onClick={handleLoadMore} disabled={loading}>
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && (
        <p>You've reached the end.</p>
      )}
    </div>
  );
}
```

## Key points

- **`hasMore` drives visibility** — the button is only rendered when `hasMore` is `true`, so it disappears automatically once the last page is loaded.
- **Detecting the end** — `hasMore` becomes `false` when the API returns fewer items than `PAGE_SIZE`, or when a `total` count is provided and we've loaded them all. Adjust this logic to match your API shape.
- **AbortController** — cancels in-flight requests on unmount or when a new page starts, avoiding "set state on unmounted component" warnings and race conditions.
- **`loading` disables the button** — prevents duplicate requests from double-clicks.
- **Error handling** — hides the button on error so the user doesn't keep retrying a broken endpoint.

If your API uses a cursor instead of page numbers, swap `page`/`PAGE_SIZE` for a `nextCursor` value and set `hasMore = Boolean(nextCursor)`.

# Load More Component

Here's a React component that fetches paginated data and conditionally renders a "Load more" button only when more items are available:

```jsx
import { useState, useEffect, useCallback } from 'react';

function ItemList() {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const PAGE_SIZE = 10;

  const fetchItems = useCallback(async (pageNum) => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(
        `https://api.example.com/items?page=${pageNum}&limit=${PAGE_SIZE}`
      );
      if (!res.ok) throw new Error(`Request failed: ${res.status}`);

      const data = await res.json();
      // Adjust based on your API shape:
      // e.g. { items: [...], total: 42 } or { results: [...], next: "url" }
      const newItems = data.items ?? [];
      const total = data.total ?? newItems.length;

      setItems((prev) => (pageNum === 1 ? newItems : [...prev, ...newItems]));
      setHasMore(pageNum * PAGE_SIZE < total);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => {
    fetchItems(1);
  }, [fetchItems]);

  const loadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchItems(nextPage);
  };

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {error && <p role="alert">Error: {error}</p>}

      {/* Only render the button when there are more items to fetch */}
      {hasMore && !error && (
        <button onClick={loadMore} disabled={loading}>
          {loading ? 'Loading…' : 'Load more'}
        </button>
      )}

      {!hasMore && items.length > 0 && <p>You've reached the end.</p>}
    </div>
  );
}

export default ItemList;
```

## Key points

1. **`hasMore` flag** — the single source of truth for whether the button renders. It's derived from the API response (e.g. `page * PAGE_SIZE < total`, or `data.next !== null`).

2. **`useCallback` on `fetchItems`** — keeps the initial-load effect stable and avoids re-fetching on every render.

3. **Functional `setItems`** — appends new items without needing `items` in the dependency array.

4. **Disabled while loading** — prevents double-clicks from firing duplicate requests.

5. **Error handling** — hides the button on error so the user isn't stuck retrying a broken request (you could instead show a "Retry" button).

## Adapting to your API

Different APIs signal "more pages" differently — replace the `setHasMore(...)` line accordingly:

| API shape | Check |
|---|---|
| `{ items, total }` | `pageNum * PAGE_SIZE < total` |
| `{ results, next }` (DRF) | `data.next !== null` |
| `{ data, hasMore }` | `data.hasMore` |
| `{ items }` only | `newItems.length === PAGE_SIZE` |

