## ProductCard component

```jsx
export default function ProductCard({
  name,
  image,
  price,
  originalPrice,
  currency = "$",
}) {
  // A product counts as discounted only if it has a higher original price.
  const isDiscounted =
    typeof originalPrice === "number" && originalPrice > price;

  const discountPercent = isDiscounted
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  return (
    <article className="product-card">
      <div className="product-card__media">
        {image && <img src={image} alt={name} className="product-card__image" />}

        {/* Badge renders only when the product is discounted */}
        {isDiscounted && (
          <span className="product-card__badge">
            Sale{discountPercent > 0 ? ` -${discountPercent}%` : ""}
          </span>
        )}
      </div>

      <h3 className="product-card__title">{name}</h3>

      <div className="product-card__prices">
        <span className="product-card__price">
          {currency}
          {price.toFixed(2)}
        </span>

        {isDiscounted && (
          <span className="product-card__original-price">
            {currency}
            {originalPrice.toFixed(2)}
          </span>
        )}
      </div>
    </article>
  );
}
```

