```jsx
export default function ProductCard({
  name,
  imageUrl,
  imageAlt,
  price,
  originalPrice, // optional — presence of a higher original price means "on sale"
  currency = "USD",
  onAddToCart,
}) {
  // A product is discounted only when it has an original price above the current price.
  const isDiscounted =
    typeof originalPrice === "number" &&
    typeof price === "number" &&
    originalPrice > price;

  const discountPercent = isDiscounted
    ? Math.round(((originalPrice - price) / originalPrice) * 100)
    : 0;

  const formatPrice = (value) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(value);

  return (
    <article className="product-card">
      <div className="product-card__media">
        <img
          src={imageUrl}
          alt={imageAlt ?? name}
          className="product-card__image"
        />

        {/* Badge renders ONLY when the product is discounted */}
        {isDiscounted && (
          <span className="product-card__badge">Sale</span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>

        <p className="product-card__price">
          {isDiscounted && (
            <span className="product-card__original-price">
              <s>{formatPrice(originalPrice)}</s>
            </span>
          )}
          <span className="product-card__current-price">
            {formatPrice(price)}
          </span>
          {isDiscounted && discountPercent > 0 && (
            <span className="product-card__discount">-{discountPercent}%</span>
          )}
        </p>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__cta"
            onClick={() => onAddToCart({ name, price })}
          >
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
