## `ProductCard.jsx`

```jsx
import { useMemo } from "react";

/** Formats a number as currency. */
export function formatCurrency(value, currency = "USD", locale = "en-US") {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).format(value);
}

/**
 * Returns discount info, or null when the product is NOT discounted.
 * A product counts as discounted only if it has a valid originalPrice
 * that is strictly greater than the current price.
 */
export function getDiscount(product) {
  const { price, originalPrice } = product;

  if (typeof price !== "number" || Number.isNaN(price)) return null;
  if (typeof originalPrice !== "number" || Number.isNaN(originalPrice)) return null;
  if (originalPrice <= 0 || price >= originalPrice) return null;

  return {
    percent: Math.round(((originalPrice - price) / originalPrice) * 100),
    amount: originalPrice - price,
  };
}

export default function ProductCard({
  product,
  currency = "USD",
  saleLabel = "Sale",
  onAddToCart,
  className = "",
}) {
  const { name, image, imageAlt, price, originalPrice } = product;

  const discount = useMemo(() => getDiscount(product), [product]);
  const isDiscounted = discount !== null;

  return (
    <article className={`product-card ${className}`.trim()}>
      <div className="product-card__media">
        {image ? (
          <img src={image} alt={imageAlt ?? name} loading="lazy" />
        ) : (
          <div className="product-card__placeholder" aria-hidden="true" />
        )}

        {/* Badge renders ONLY when the product is discounted */}
        {isDiscounted && (
          <span
            className="product-card__badge"
            aria-label={`${saleLabel}: ${discount.percent}% off`}
          >
            {saleLabel}
            {discount.percent > 0 && (
              <span className="product-card__badge-percent">
                -{discount.percent}%
              </span>
            )}
          </span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>

        <p className="product-card__price">
          <span className="product-card__price-current">
            {formatCurrency(price, currency)}
          </span>

          {isDiscounted && (
            <s className="product-card__price-original">
              {formatCurrency(originalPrice, currency)}
            </s>
          )}
        </p>

        {onAddToCart && (
          <button type="button" onClick={() => onAddToCart(product)}>
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
```

