### Notes on the discount logic

- The badge is driven by a single source of truth (`getDiscount`), so the badge and the strikethrough price can never disagree.
- `originalPrice <= price` (equal, higher, missing, `0`, or `NaN`) means **no badge** — this avoids the common bug of showing "Sale" on a full-price item.
- The percentage is rounded to the nearest whole number; a 0% discount (e.g. a tiny rounding difference) still shows the "Sale" label but hides the `-0%` text.
- If your API already returns a `discountPercent` or `onSale` flag, you can swap `getDiscount` for that field instead of computing it.

## `ProductCard.tsx`

```tsx
import { useMemo } from "react";
import styles from "./ProductCard.module.css";

export type ProductCardProps = {
  id: string;
  name: string;
  imageUrl: string;
  /** Current (sale) price */
  price: number;
  /** Original price before discount. Omit for non-discounted products. */
  originalPrice?: number;
  currency?: string;
  href?: string;
};

export function ProductCard({
  id,
  name,
  imageUrl,
  price,
  originalPrice,
  currency = "USD",
  href,
}: ProductCardProps) {
  // A product counts as "on sale" only if it has an original price that is
  // strictly greater than the current price.
  const discountPercent = useMemo(() => {
    if (originalPrice == null || originalPrice <= price) return 0;
    return Math.round(((originalPrice - price) / originalPrice) * 100);
  }, [originalPrice, price]);

  const isOnSale = discountPercent > 0;

  const formatted = (value: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(value);

  return (
    <article className={styles.card} aria-labelledby={`product-${id}-name`}>
      <div className={styles.media}>
        <img src={imageUrl} alt={name} className={styles.image} loading="lazy" />

        {isOnSale && (
          <span className={styles.badge} data-testid="sale-badge">
            Sale
          </span>
        )}
      </div>

      <div className={styles.body}>
        <h3 id={`product-${id}-name`} className={styles.name}>
          {href ? <a href={href}>{name}</a> : name}
        </h3>

        <p className={styles.priceRow}>
          <span className={isOnSale ? styles.salePrice : styles.price}>
            {formatted(price)}
          </span>

          {isOnSale && (
            <>
              <s className={styles.originalPrice}>{formatted(originalPrice!)}</s>
              <span className={styles.discount}>-{discountPercent}%</span>
            </>
          )}
        </p>
      </div>
    </article>
  );
}
```

