The badge is rendered conditionally, so it never appears for full-price products. If your data model uses an explicit `discount` or `onSale` flag instead of comparing prices, swap the `isDiscounted` check for that prop.

Here's a TypeScript React component with the sale logic isolated so it's easy to test and reuse.

## `ProductCard.tsx`

```tsx
import { useMemo } from 'react';
import styles from './ProductCard.module.css';

export interface Product {
  id: string;
  name: string;
  price: number;
  /** The pre-discount price. Omit (or pass null) if the product isn't discounted. */
  originalPrice?: number | null;
  imageUrl?: string;
  currency?: string;
}

interface ProductCardProps {
  product: Product;
  onAddToCart?: (product: Product) => void;
}

/**
 * A product is considered "on sale" only when it has an originalPrice that is
 * strictly greater than the current price. This avoids flagging products where
 * the original price is missing, equal, or higher than the current price.
 */
export function getDiscount(product: Product): number | null {
  const { price, originalPrice } = product;

  if (typeof originalPrice !== 'number' || originalPrice <= 0) return null;
  if (typeof price !== 'number' || price < 0) return null;
  if (originalPrice <= price) return null;

  return Math.round(((originalPrice - price) / originalPrice) * 100);
}

export default function ProductCard({ product, onAddToCart }: ProductCardProps) {
  const discountPercent = useMemo(() => getDiscount(product), [product]);
  const isOnSale = discountPercent !== null;
  const currency = product.currency ?? 'USD';

  const formatPrice = (value: number) =>
    new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(value);

  return (
    <article className={styles.card} aria-labelledby={`product-${product.id}-name`}>
      <div className={styles.media}>
        {product.imageUrl && (
          <img src={product.imageUrl} alt="" className={styles.image} loading="lazy" />
        )}

        {isOnSale && (
          <span className={styles.badge} aria-label={`On sale, ${discountPercent}% off`}>
            Sale
            <span className={styles.badgePercent}>-{discountPercent}%</span>
          </span>
        )}
      </div>

      <div className={styles.body}>
        <h3 id={`product-${product.id}-name`} className={styles.name}>
          {product.name}
        </h3>

        <div className={styles.prices}>
          <span className={styles.price}>{formatPrice(product.price)}</span>

          {isOnSale && (
            <s className={styles.originalPrice} aria-label={`Original price ${formatPrice(product.originalPrice!)}`}>
              {formatPrice(product.originalPrice!)}
            </s>
          )}
        </div>

        <button
          type="button"
          className={styles.addButton}
          onClick={() => onAddToCart?.(product)}
        >
          Add to cart
        </button>
      </div>
    </article>
  );
}
```

