**Key point:** the badge is conditionally rendered with `{isDiscounted && ...}`, so it never appears for full-price products. If your data model uses an explicit flag instead of a compare-at price, swap the check for `product.onSale` and keep the rest unchanged.

Here's a reusable product card component. The "Sale" badge renders only when a `compareAtPrice` exists and is greater than the current `price`.

```tsx
// ProductCard.tsx
import { useMemo } from "react";

export type Product = {
  id: string;
  name: string;
  price: number;
  compareAtPrice?: number; // original price before discount
  imageUrl?: string;
  currency?: string;
};

type ProductCardProps = {
  product: Product;
  onAddToCart?: (product: Product) => void;
};

export function ProductCard({ product, onAddToCart }: ProductCardProps) {
  const { name, price, compareAtPrice, imageUrl, currency = "USD" } = product;

  // A product is "on sale" only if it has a compare-at price higher than the current price.
  const isDiscounted =
    typeof compareAtPrice === "number" && compareAtPrice > price;

  const discountPercent = useMemo(() => {
    if (!isDiscounted || !compareAtPrice) return 0;
    return Math.round(((compareAtPrice - price) / compareAtPrice) * 100);
  }, [isDiscounted, compareAtPrice, price]);

  const formatPrice = (value: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency }).format(value);

  return (
    <article className="product-card">
      <div className="product-card__media">
        {imageUrl && (
          <img src={imageUrl} alt={name} loading="lazy" className="product-card__image" />
        )}

        {isDiscounted && (
          <span className="product-card__badge" aria-label={`On sale, ${discountPercent}% off`}>
            Sale
          </span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__title">{name}</h3>

        <p className="product-card__price">
          {isDiscounted && (
            <>
              <span className="product-card__price-original">
                {formatPrice(compareAtPrice!)}
              </span>{" "}
              <span className="product-card__price-sale">{formatPrice(price)}</span>
              <span className="product-card__price-off">
                ({discountPercent}% off)
              </span>
            </>
          )}
          {!isDiscounted && formatPrice(price)}
        </p>

        {onAddToCart && (
          <button
            type="button"
            className="product-card__cta"
            onClick={() => onAddToCart(product)}
          >
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}
```

