 * @property {string|number} id
 * @property {string} name
 * @property {string} [imageUrl]
 * @property {number} price                Current (sale) price
 * @property {number} [originalPrice]      Compare-at price; badge shows only if > price
 * @property {string} [currency]
 * @property {string} [badgeText]          Defaults to "Sale"
 * @property {boolean} [showDiscountPercent]
 * @property {boolean} [inStock]
 * @property {() => void} [onAddToCart]
