          />
        ) : (
          <div style={styles.imageFallback} aria-hidden="true">
            No image
          </div>
        )}

        {/* Badge renders ONLY for discounted products */}
        {isDiscounted && (
          <span
            style={styles.badge}
            aria-label={`${badgeText}, ${discountPercent} percent off`}
          >
            {badgeText}
            {showDiscountPercent && discountPercent > 0 && (
              <span style={styles.badgePercent}>-{discountPercent}%</span>
            )}
          </span>
        )}
      </div>

      <div style={styles.body}>
        <h3 id={titleId} style={styles.name}>
          {name}
        </h3>

        <div style={styles.priceRow}>
          <span style={styles.price}>{formatPrice.format(price)}</span>
          {isDiscounted && (
            <span style={styles.originalPrice}>
              {formatPrice.format(originalPrice)}
            </span>
          )}
        </div>

        <button
          type="button"
          style={{
            ...styles.cta,
            ...(inStock ? null : styles.ctaDisabled),
          }}
          disabled={!inStock}
          onClick={() => onAddToCart?.({ id, name, price })}
        >
          {inStock ? "Add to cart" : "Out of stock"}
        </button>
      </div>
    </article>
  );
}
