## ProductCard Component

```jsx
export default function ProductCard({ product }) {
  const { name, imageUrl, price, compareAtPrice, currency = "$" } = product;

  // A product counts as discounted when it has a compare-at price
  // that is higher than the current selling price.
  const isDiscounted =
    compareAtPrice != null && Number(compareAtPrice) > Number(price);

  const discountPercent = isDiscounted
    ? Math.round((1 - price / compareAtPrice) * 100)
    : 0;

  return (
    <article className="product-card">
      <div className="product-card__media">
        <img src={imageUrl} alt={name} className="product-card__image" />

        {/* Badge renders ONLY when the product is discounted */}
        {isDiscounted && (
          <span className="product-card__badge">Sale</span>
        )}
      </div>

      <div className="product-card__body">
        <h3 className="product-card__name">{name}</h3>

        <p className="product-card__price">
          {isDiscounted ? (
            <>
              <span className="product-card__price--sale">
                {currency}
                {price.toFixed(2)}
              </span>
              <span className="product-card__price--original">
                {currency}
                {compareAtPrice.toFixed(2)}
              </span>
            </>
          ) : (
            <span className="product-card__price--regular">
              {currency}
              {price.toFixed(2)}
            </span>
          )}
        </p>

        {isDiscounted && (
          <p className="product-card__discount">
            Save {discountPercent}%
          </p>
        )}
      </div>
    </article>
  );
}
