## `ProductCard.tsx`

```tsx
import { memo } from 'react';
import styles from './ProductCard.module.css';

export type Product = {
  id: string;
  name: string;
  imageUrl: string;
  /** Current selling price */
  price: number;
  /** Original price — present only if the product was marked down */
  compareAtPrice?: number;
  currency?: string;
};

type Props = {
  product: Product;
  /** Optional override for the badge text */
  badgeLabel?: string;
  onSelect?: (product: Product) => void;
};

/** A product is "on sale" only if it has an original price that is higher than the current one. */
export function isDiscounted(product: Product): boolean {
  const { price, compareAtPrice } = product;
  return (
    typeof compareAtPrice === 'number' &&
    compareAtPrice > 0 &&
    compareAtPrice > price
  );
}

/** Percentage off, rounded to the nearest whole number. */
export function discountPercent(product: Product): number {
  if (!isDiscounted(product)) return 0;
  const { price, compareAtPrice } = product;
  return Math.round(((compareAtPrice! - price) / compareAtPrice!) * 100);
}

function ProductCardComponent({ product, badgeLabel = 'Sale', onSelect }: Props) {
  const discounted = isDiscounted(product);
  const percent = discountPercent(product);

  const formatted = (value: number) =>
    new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: product.currency ?? 'USD',
    }).format(value);

  return (
    <article className={styles.card}>
      <div className={styles.media}>
        <img src={product.imageUrl} alt={product.name} loading="lazy" />

        {/* Badge renders only when the product is actually discounted */}
        {discounted && (
          <span className={styles.badge} data-testid="sale-badge">
            {badgeLabel}
            {percent > 0 && <span className={styles.badgePercent}>-{percent}%</span>}
          </span>
        )}
      </div>

      <div className={styles.body}>
        <h3 className={styles.title}>{product.name}</h3>

        <p className={styles.price}>
          {discounted ? (
            <>
              <span className={styles.current}>{formatted(product.price)}</span>{' '}
              <del className={styles.original}>{formatted(product.compareAtPrice!)}</del>
              <span className="srOnly">
                , reduced from {formatted(product.compareAtPrice!)}
              </span>
            </>
          ) : (
            <span className={styles.current}>{formatted(product.price)}</span>
          )}
        </p>

        {onSelect && (
          <button type="button" className={styles.cta} onClick={() => onSelect(product)}>
            Add to cart
          </button>
        )}
      </div>
    </article>
  );
}

export const ProductCard = memo(ProductCardComponent);
export default ProductCard;
```

