Here's a complete example that fetches items page by page and only renders the button when the server says more data exists:

```jsx
import { useEffect, useState } from "react";

export default function ItemList({ fetchPage }) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);

    fetchPage(page)
      .then(({ items: newItems, hasMore: more }) => {
        if (cancelled) return;
        setItems((prev) => [...prev, ...newItems]);
        setHasMore(more);
      })
      .catch(console.error)
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true; // avoid state updates after unmount / stale requests
    };
  }, [page, fetchPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {/* Button only exists when there are more items to fetch */}
      {hasMore && (
        <button onClick={() => setPage((p) => p + 1)} disabled={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}
    </div>
  );
}
```

**Usage** — the API returns a `hasMore` flag (or you can derive it, e.g. `items.length < total`):

```jsx
<ItemList
  fetchPage={(page) =>
    fetch(`/api/items?page=${page}&limit=20`).then((r) => r.json())
  }
/>
```

Key points:
- `hasMore` is the single source of truth for showing the button; when the last page returns `hasMore: false`, the button disappears.
- `loading` disables the button to prevent duplicate requests while a page is in flight.
- The `cancelled` flag prevents state updates from a stale/unmounted request.

