## Approach

The button's visibility depends on a single piece of state: `hasMore`. It's `true` until we know the server has no more data — either because the server told us (`hasMore: false`) or because the last page came back with fewer items than we requested.

```tsx
import { useCallback, useEffect, useRef, useState } from 'react';

/* ------------------------------------------------------------------ */
/* Hook: paginated fetching + "is there more?" logic                   */
/* ------------------------------------------------------------------ */

type Page<T> = { items: T[]; hasMore?: boolean };

interface UsePaginatedListOptions<T> {
  /** Fetch one page. Return an array, or { items, hasMore } for server-driven paging. */
  fetchPage: (page: number, pageSize: number) => Promise<Page<T> | T[]>;
  pageSize?: number;
  initialItems?: T[];
}

export function usePaginatedList<T>({
  fetchPage,
  pageSize = 20,
  initialItems = [],
}: UsePaginatedListOptions<T>) {
  const [items, setItems] = useState<T[]>(initialItems);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  // Refs guard against double-clicks and stale responses after unmount.
  const loadingRef = useRef(false);
  const mountedRef = useRef(true);
  const requestIdRef = useRef(0);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const loadMore = useCallback(async () => {
    if (loadingRef.current) return; // ignore clicks while a request is in flight
    loadingRef.current = true;

    const requestId = ++requestIdRef.current;
    const nextPage = page + 1;

    setIsLoading(true);
    setError(null);

    try {
      const result = await fetchPage(nextPage, pageSize);

      // A newer request started, or we unmounted — discard this response.
      if (!mountedRef.current || requestId !== requestIdRef.current) return;

      const newItems = Array.isArray(result) ? result : result.items;
      const serverHasMore = Array.isArray(result) ? undefined : result.hasMore;

      setItems((prev) => [...prev, ...newItems]);
      setPage(nextPage);
      // Server flag wins; otherwise infer from a short page.
      setHasMore(serverHasMore ?? newItems.length >= pageSize);
    } catch (err) {
      if (!mountedRef.current || requestId !== requestIdRef.current) return;
      setError(err instanceof Error ? err : new Error('Failed to load items'));
    } finally {
      if (mountedRef.current && requestId === requestIdRef.current) {
        setIsLoading(false);
        loadingRef.current = false;
      }
    }
  }, [fetchPage, page, pageSize]);

  const retry = useCallback(() => {
    setError(null);
    void loadMore();
  }, [loadMore]);

  return { items, hasMore, isLoading, error, loadMore, retry };
}

/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

interface LoadMoreListProps<T> {
  fetchPage: (page: number, pageSize: number) => Promise<Page<T> | T[]>;
  pageSize?: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  keyExtractor?: (item: T, index: number) => string | number;
  loadMoreLabel?: string;
  emptyMessage?: string;
}

export function LoadMoreList<T>({
  fetchPage,
  pageSize = 20,
  renderItem,
  keyExtractor = (_item, index) => index,
  loadMoreLabel = 'Load more',
  emptyMessage = 'No items.',
}: LoadMoreListProps<T>) {
  const { items, hasMore, isLoading, error, loadMore, retry } = usePaginatedList<T>({
    fetchPage,
    pageSize,
  });

  if (items.length === 0 && !isLoading && !error) {
    return <p>{emptyMessage}</p>;
  }

  return (
    <div>
      <ul>
        {items.map((item, index) => (
          <li key={keyExtractor(item, index)}>{renderItem(item, index)}</li>
        ))}
      </ul>

      {error ? (
        <div role="alert">
          <p>{error.message}</p>
          <button type="button" onClick={retry}>
            Try again
          </button>
        </div>
      ) : (
        hasMore && (
          <button type="button" onClick={() => void loadMore()} disabled={isLoading}>
            {isLoading ? 'Loading…' : loadMoreLabel}
          </button>
        )
      )}
    </div>
  );
}
```

