## Full Example with Data Fetching

```jsx
import { useState, useEffect } from 'react';

export function ItemList({ pageSize = 10 }) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function fetchItems() {
      setIsLoading(true);
      try {
        const res = await fetch(`/api/items?page=${page}&limit=${pageSize}`);
        const data = await res.json();

        if (cancelled) return;

        setItems((prev) => [...prev, ...data.items]);
        // The server tells us whether more pages exist
        setHasMore(data.hasMore);
      } catch (err) {
        console.error(err);
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    }

    fetchItems();
    return () => {
      cancelled = true;
    };
  }, [page, pageSize]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {hasMore && (
        <button onClick={() => setPage((p) => p + 1)} disabled={isLoading}>
          {isLoading ? 'Loading…' : 'Load more'}
        </button>
      )}
    </div>
  );
}
```

## Key Points

- **Conditional rendering** — `{hasMore && <button>…</button>}` means the button is removed from the DOM entirely (not just hidden) when there are no more items.
- **Loading state** — disables the button and shows a "Loading…" label to prevent duplicate requests.
- **Cleanup in `useEffect`** — the `cancelled` flag avoids setting state after unmount or on a stale request.
- **Server-driven `hasMore`** — the most reliable source of truth, since the client doesn't know the total count until the server tells it.

### Alternative: derive `hasMore` from item count

If your API returns exactly `pageSize` items until the end, you can infer it:

```jsx
const hasMore = data.items.length === pageSize;
```

This is simpler but slightly less precise — it requires one extra request to discover you're at the end, and it breaks if the server returns fewer items for other reasons (e.g. filtering).

## The core idea

`hasMore` should be **derived**, not stored separately, so it can never get out of sync with the data:

- If the API tells you the total → `items.length < total`
- If it doesn't → track whether the last page came back full (`lastPage.length === pageSize`)

The button renders **only** when `hasMore` is true.

---

## 1. The hook: `useLoadMore`

```jsx
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

/**
 * @param {Object}   options
 * @param {Function} options.fetchItems  ({ page, pageSize }) => Promise<{ items: any[], total?: number }>
 * @param {number}   options.pageSize
 * @param {any[]}    options.initialItems
 * @param {number|null} options.initialTotal
 * @param {any}      options.resetKey  change this (e.g. a filter id) to reset the list
 */
export function useLoadMore({
  fetchItems,
  pageSize = 20,
  initialItems = [],
  initialTotal = null,
  resetKey = null,
}) {
  const [items, setItems] = useState(initialItems);
  const [total, setTotal] = useState(initialTotal);
  const [page, setPage] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastPageWasFull, setLastPageWasFull] = useState(true);

  // Refs (not state) so the guard is accurate even within the same tick.
  const loadingRef = useRef(false);
  const requestIdRef = useRef(0);
  const isMountedRef = useRef(true);

  useEffect(() => () => { isMountedRef.current = false; }, []);

  const loadMore = useCallback(async () => {
    if (loadingRef.current) return; // prevents double-click / duplicate requests
    loadingRef.current = true;

    const requestId = ++requestIdRef.current;
    setIsLoading(true);
    setError(null);

    try {
      const nextPage = page + 1;
      const result = await fetchItems({ page: nextPage, pageSize });

      // Ignore stale responses (e.g. a reset happened while this was in flight).
      if (!isMountedRef.current || requestId !== requestIdRef.current) return;

      const newItems = result?.items ?? [];
      setItems((prev) => [...prev, ...newItems]);
      if (typeof result?.total === "number") setTotal(result.total);
      setLastPageWasFull(newItems.length >= pageSize);
      setPage(nextPage);
    } catch (err) {
      if (!isMountedRef.current || requestId !== requestIdRef.current) return;
      setError(err);
    } finally {
      if (isMountedRef.current && requestId === requestIdRef.current) {
        loadingRef.current = false;
        setIsLoading(false);
      }
    }
  }, [fetchItems, page, pageSize]);

  // Reset when the caller signals a new query/filter.
  useEffect(() => {
    requestIdRef.current += 1;      // invalidate in-flight requests
    loadingRef.current = false;
    setItems(initialItems);
    setTotal(initialTotal);
    setPage(0);
    setLastPageWasFull(true);
    setError(null);
    setIsLoading(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resetKey]);

  const hasMore = useMemo(() => {
    if (total != null) return items.length < total;   // server told us the total
    return lastPageWasFull;                            // fall back to "full page" heuristic
  }, [items.length, total, lastPageWasFull]);

  return { items, hasMore, isLoading, error, loadMore };
}
```

