      <ul>
        {items.map((item, index) => (
          <li key={item.id ?? index}>{renderItem(item)}</li>
        ))}
      </ul>

      {/* The button exists ONLY when there is more to fetch */}
      {hasMore && (
        <button
          type="button"
          onClick={onLoadMore}
          disabled={isLoading}
          aria-busy={isLoading}
        >
          {isLoading ? "Loading…" : error ? "Try again" : "Load more"}
        </button>
      )}

      {error && !hasMore && (
        <p role="alert" className="error">
          Could not load more items.
        </p>
      )}
    </div>
  );
}
