export default function ArticleList({ category }) {
  const fetchItems = useCallback(
    ({ page, pageSize }) =>
      fetch(`/api/articles?category=${category}&page=${page}&pageSize=${pageSize}`)
        .then((r) => {
          if (!r.ok) throw new Error("Request failed");
          return r.json(); // { items: [...], total: 137 }
        }),
    [category]
  );

