    fetchItems,
    pageSize: 20,
    resetKey: category, // changing the category resets the list
  });

  return (
    <LoadMoreList
      items={items}
      hasMore={hasMore}
      isLoading={isLoading}
      error={error}
      onLoadMore={loadMore}
      renderItem={(a) => <ArticleCard article={a} />}
      emptyMessage="No articles in this category."
    />
  );
}
