## Edge cases handled

| Situation | Behaviour |
|---|---|
| Server returns `total` | Button hides exactly when `items.length === total` |
| No `total` from server | Button hides when a page comes back with fewer than `pageSize` items |
| User double-clicks | `loadingRef` blocks the second request |
| Request fails | Button stays visible and becomes "Try again" |
| Component unmounts mid-request | Stale response is ignored (`isMountedRef`) |
| Filter/search changes | `resetKey` clears items and invalidates in-flight requests |

### Optional: infinite scroll instead of a button

Swap the button for an `IntersectionObserver` and keep the same `hasMore` guard:

```jsx
const ref = useRef(null);
useEffect(() => {
  const node = ref.current;
  if (!node || !hasMore) return;
  const observer = new IntersectionObserver(([entry]) => {
    if (entry.isIntersecting) loadMore();
  });
  observer.observe(node);
  return () => observer.disconnect();
}, [hasMore, loadMore]);
```

The `hasMore` check in the effect is what stops the observer from firing requests forever once the end is reached.

```jsx
import { useEffect, useState } from "react";

export default function ItemList({ fetchPage }) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setLoading(true);
      try {
        const { items: newItems, hasMore: more } = await fetchPage(page);
        if (cancelled) return;
        setItems((prev) => [...prev, ...newItems]);
        setHasMore(more);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    load();
    return () => {
      cancelled = true;
    };
  }, [page, fetchPage]);

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

      {hasMore && (
        <button onClick={() => setPage((p) => p + 1)} disabled={loading}>
          {loading ? "Loading…" : "Load more"}
        </button>
      )}
    </div>
  );
}
```

**Example usage with a fake API:**

```jsx
const ALL_ITEMS = Array.from({ length: 25 }, (_, i) => ({
  id: i,
  name: `Item ${i + 1}`,
}));

const PAGE_SIZE = 10;

async function fetchPage(page) {
  await new Promise((r) => setTimeout(r, 500)); // simulate network delay
  const start = (page - 1) * PAGE_SIZE;
  const items = ALL_ITEMS.slice(start, start + PAGE_SIZE);
  return { items, hasMore: start + PAGE_SIZE < ALL_ITEMS.length };
