## 2. `useLoadMore.js`

```jsx
import { useCallback, useEffect, useRef, useState } from 'react';

export default function useLoadMore(fetchPage, { initialPage = 0 } = {}) {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(initialPage);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const requestId = useRef(0); // guards against out-of-order responses

  const load = useCallback(
    async (targetPage) => {
      const id = ++requestId.current;
      setLoading(true);
      setError(null);
      try {
        const { items: newItems, hasMore: more } = await fetchPage(targetPage);
        if (id !== requestId.current) return; // stale response, ignore

        setItems((prev) => [...prev, ...newItems]);
        setHasMore(more);
        setPage(targetPage);
      } catch (err) {
        if (id !== requestId.current) return;
        setError(err);
      } finally {
        if (id === requestId.current) setLoading(false);
      }
    },
    [fetchPage]
  );

  // Initial load
  useEffect(() => {
    load(initialPage);
  }, [load, initialPage]);

  const loadMore = useCallback(() => {
    if (loading || !hasMore) return;
    load(page + 1);
  }, [loading, hasMore, page, load]);

  return { items, hasMore, loading, error, loadMore, reload: () => load(initialPage) };
}
```

