        setHasMore(items.length + data.length < total);
      } catch (err) {
        console.error("Failed to load items:", err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    loadItems();
    return () => {
      cancelled = true;
    };
  }, [page]);

  function handleLoadMore() {
    setPage((p) => p + 1);
  }

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>

